// Token Launch Radar — Research Desk dashboard.
// Renders window.RADAR (zz-data.js, generated by main.ts from the snapshot).
// No network, no clock, no randomness: the page shows one sealed snapshot.

const R = window.RADAR;
const meta = R.meta;
const rows = R.rows;

const usdFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
const intFmt = new Intl.NumberFormat('en-US');
const fmt$ = (v) => usdFmt.format(v);
const fmtInt = (v) => intFmt.format(v);
const fmtMult = (v) => `x${v.toFixed(2)}`;
const fmtPct = (v) => (v === null ? '—' : `${v > 0 ? '+' : ''}${v.toFixed(1)}%`);
const fmtAge = (days) => {
  if (days === null) return 'unrecorded';
  if (days < 365) return `${days}d`;
  return `${(days / 365).toFixed(1)}y`;
};
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

document.getElementById('coverage').textContent =
  `${fmtInt(meta.board_rows)} pre-token protocols ranked · ${meta.watchlist_covered}/${meta.watchlist_total} watchlist covered · ` +
  `${meta.early_candidates} early candidates found beyond it · snapshot of ${meta.as_of} · model ${meta.model_version}`;

// The completeness ledger strip: proof, in one band, that every protocol in
// the snapshot is accounted for — priced, ranked, or set aside with a reason.
(function renderLedgerStrip() {
  const g = {};
  for (const group of meta.ledger) g[group.key] = group.count;
  const ranked = g.rankedWatchlist + g.rankedEarly;
  const aside = g.outCategory + g.outVersioned + g.outWrapped + g.outExchange;
  const parts = [
    `${fmtInt(g.comparable)} priced as comparables`,
    `${fmtInt(g.deadPriced + g.noCap)} record a token without a usable price`,
    `${fmtInt(ranked)} ranked (${fmtInt(g.rankedWatchlist)} watchlist + ${fmtInt(g.rankedEarly)} early)`,
    `${fmtInt(aside)} set aside by rule`,
  ];
  document.getElementById('ledger').innerHTML =
    `<strong>Completeness ledger — all ${fmtInt(meta.snapshot_total)} protocols counted:</strong> ` +
    parts.map((p) => `<span class="lgroup">${p}</span>`).join(' · ') +
    ` · <span class="ltotal">= ${fmtInt(meta.snapshot_total)} of ${fmtInt(meta.snapshot_total)}</span>` +
    ` · <a href="#/methodology">the full ledger</a>`;
})();

const boardState = {
  q: '', category: 'all', chain: 'all', verdict: 'all', band: 'all',
  watchlistOnly: false, sortKey: 'rank', sortDir: 1,
};

function categories() { return [...new Set(rows.map((r) => r.category))].sort(); }
function chains() { return [...new Set(rows.map((r) => r.chain))].sort(); }

function bandOf(v) {
  if (v >= 1_000_000_000) return 'b1';
  if (v >= 100_000_000) return 'b2';
  if (v >= 10_000_000) return 'b3';
  return 'b4';
}

function filteredRows() {
  let out = rows.filter((r) =>
    (boardState.category === 'all' || r.category === boardState.category) &&
    (boardState.chain === 'all' || r.chain === boardState.chain) &&
    (boardState.verdict === 'all' || r.verdict === boardState.verdict) &&
    (boardState.band === 'all' || bandOf(r.implied_value_usd) === boardState.band) &&
    (!boardState.watchlistOnly || r.watchlist) &&
    (boardState.q === '' || r.name.toLowerCase().includes(boardState.q) || r.slug.includes(boardState.q)));
  const key = boardState.sortKey;
  const dir = boardState.sortDir;
  const val = (r) => key === 'rank' ? r.implied_value_usd
    : key === 'implied' ? r.implied_value_usd
    : key === 'tvl' ? r.tvl_usd
    : key === 'change' ? (r.change_7d === null ? -Infinity : r.change_7d)
    : key === 'age' ? (r.age_days === null ? -1 : r.age_days)
    : r.implied_value_usd;
  out = [...out].sort((a, b) => (val(a) - val(b)) * dir || (a.slug < b.slug ? -1 : 1));
  return out;
}

function boardRowsHtml(list) {
  return list.map((r) => {
    const rank = rows.indexOf(r) + 1;
    const chg = r.change_7d === null ? '<td class="num">—</td>'
      : `<td class="num ${r.change_7d >= 0 ? 'pos' : 'neg'}">${fmtPct(r.change_7d)}</td>`;
    return `<tr>
      <td class="num">${rank}</td>
      <td><a class="plink" href="#/protocol/${r.slug}">${esc(r.name)}</a>${r.watchlist ? ' <span class="star" title="On the competition watchlist">★</span>' : ''}<div class="sub">${esc(r.slug)}</div></td>
      <td>${esc(r.category)}</td>
      <td>${esc(r.chain)}</td>
      <td class="num">${fmt$(r.tvl_usd)}</td>
      ${chg}
      <td class="num">${fmtAge(r.age_days)}</td>
      <td class="num">${fmt$(r.implied_value_usd)}<div class="interval">P25–P75 <b>${fmt$(r.interval_lo)} – ${fmt$(r.interval_hi)}</b></div></td>
      <td><span class="badge ${r.verdict === 'Farm now' ? 'farm' : r.verdict === 'Watch' ? 'watch' : 'skip'}">${r.verdict}</span></td>
    </tr>`;
  }).join('');
}

function renderBoard(app) {
  const cats = categories().map((c) => `<option value="${esc(c)}">${esc(c)}</option>`).join('');
  const chs = chains().map((c) => `<option value="${esc(c)}">${esc(c)}</option>`).join('');
  app.innerHTML = `
    <p class="lede">Every protocol here <strong>records no token</strong> and holds at least $5M of TVL. Each is priced the same way:
    its TVL times the market-cap-to-TVL multiple the snapshot's own tokened protocols trade at in its category, adjusted for
    operating age and for decisive momentum only. Every term was fitted on the snapshot's ${meta.comparables} usable comparables and
    kept or dropped by held-out ablation — the evidence is on the methodology page. Under each price sits the model's own
    uncertainty interval, fitted from its leave-one-out residuals: these prices are estimates, and the page says how wide they are.</p>
    <div class="toolbar">
      <input type="search" id="f-q" placeholder="Search name or slug" value="${esc(boardState.q)}">
      <label>Category <select id="f-cat"><option value="all">All</option>${cats}</select></label>
      <label>Chain <select id="f-chain"><option value="all">All</option>${chs}</select></label>
      <label>Verdict <select id="f-verdict"><option value="all">All</option><option>Farm now</option><option>Watch</option><option>Skip</option></select></label>
      <label>Implied value <select id="f-band"><option value="all">All bands</option><option value="b1">$1B and up</option><option value="b2">$100M – $1B</option><option value="b3">$10M – $100M</option><option value="b4">Under $10M</option></select></label>
      <label><input type="checkbox" id="f-wl" ${boardState.watchlistOnly ? 'checked' : ''}> Watchlist only</label>
    </div>
    <p class="resultline" id="resultline"></p>
    <table class="board">
      <thead><tr>
        <th data-k="rank">#</th><th>Protocol</th><th>Category</th><th>Chain</th>
        <th data-k="tvl" class="num">TVL</th><th data-k="change" class="num">7d</th>
        <th data-k="age" class="num">Age</th><th data-k="implied" class="num">Implied value</th><th>Verdict</th>
      </tr></thead>
      <tbody id="boardbody"></tbody>
    </table>`;
  const $ = (id) => document.getElementById(id);
  $('f-cat').value = boardState.category;
  $('f-chain').value = boardState.chain;
  $('f-verdict').value = boardState.verdict;
  $('f-band').value = boardState.band;
  const refreshBody = () => {
    const list = filteredRows();
    $('boardbody').innerHTML = boardRowsHtml(list);
    $('resultline').textContent = `Showing ${fmtInt(list.length)} of ${fmtInt(rows.length)} ranked protocols`;
  };
  $('f-q').addEventListener('input', (e) => { boardState.q = e.target.value.toLowerCase(); refreshBody(); });
  $('f-cat').addEventListener('change', (e) => { boardState.category = e.target.value; refreshBody(); });
  $('f-chain').addEventListener('change', (e) => { boardState.chain = e.target.value; refreshBody(); });
  $('f-verdict').addEventListener('change', (e) => { boardState.verdict = e.target.value; refreshBody(); });
  $('f-band').addEventListener('change', (e) => { boardState.band = e.target.value; refreshBody(); });
  $('f-wl').addEventListener('change', (e) => { boardState.watchlistOnly = e.target.checked; refreshBody(); });
  app.querySelectorAll('th[data-k]').forEach((th) => {
    th.addEventListener('click', () => {
      const k = th.getAttribute('data-k');
      if (boardState.sortKey === k) boardState.sortDir *= -1;
      else { boardState.sortKey = k; boardState.sortDir = k === 'rank' || k === 'implied' || k === 'tvl' ? -1 : 1; }
      refreshBody();
    });
  });
  refreshBody();
}

function renderDetail(app, slug) {
  const r = rows.find((x) => x.slug === slug);
  if (!r) { app.innerHTML = '<p>Protocol not on the board.</p>'; return; }
  const rank = rows.indexOf(r) + 1;
  const w = r.walk;
  const capped = w.multipleSource.includes('capped');
  const walkRows = [
    ['TVL (snapshot)', fmt$(r.tvl_usd), 'the protocol\'s own total value locked'],
    [`Category multiple — ${esc(r.category)}`, fmtMult(w.multiple),
      `${esc(w.multipleSource)}${capped ? `; the cap is the 95th percentile of all observed multiples, ${fmtMult(meta.multiple_cap)}` : ''}`],
    ['Momentum factor', fmtMult(w.momentum),
      r.change_7d === null ? 'no 7-day change recorded, so no momentum adjustment'
        : Math.abs(r.change_7d) >= 35 ? `7-day TVL change of ${fmtPct(r.change_7d)} clears the +/-35% band`
        : `7-day TVL change of ${fmtPct(r.change_7d)} sits inside the +/-35% band, so momentum does not move the price`],
    ['Maturity factor', fmtMult(w.maturity),
      w.ageSubstituted ? `no listing date recorded; priced at the median comparable age of ${fmtInt(meta.median_age_days)} days`
        : `operating age ${fmtInt(w.ageDays)} days`],
    ['Implied value if it launches', fmt$(r.implied_value_usd), 'TVL x multiple x momentum x maturity, rounded'],
  ].map((row) => `<tr><td>${row[0]}</td><td class="num"><strong>${row[1]}</strong></td><td>${row[2]}</td></tr>`).join('');
  app.innerHTML = `
    <p class="back"><a href="#/">← Back to the board</a></p>
    <h2>${esc(r.name)} ${r.watchlist ? '<span class="star">★ watchlist</span>' : ''}</h2>
    <p class="sub">Rank #${rank} of ${fmtInt(rows.length)} · ${esc(r.category)} · ${esc(r.chains.join(', '))}</p>
    <div class="card verdictbox ${r.verdict === 'Skip' ? 'skip' : ''}">
      <h3>${r.verdict}</h3>
      <p>${esc(r.verdict_reason)}</p>
    </div>
    <div class="card">
      <h3>How this price is built</h3>
      <table class="walk">${walkRows}</table>
      <p class="sub">Pre-token and already-trading protocols are kept separate throughout: ${esc(r.name)} is priced because it records no token;
      the ${fmtInt(meta.comparables)} protocols that do record one appear only as comparables, never as rows.</p>
    </div>
    <div class="card">
      <h3>How wide the uncertainty is</h3>
      <p>The point price above is the middle of a wide, honest range. Fitted from this model's own leave-one-out residuals
      on the ${fmtInt(meta.comparables)} comparables, the middle half of outcomes (P25–P75) for a price like this one runs
      <strong>${fmt$(r.interval_lo)} – ${fmt$(r.interval_hi)}</strong>, and the wider P10–P90 range runs
      <strong>${fmt$(r.wide_lo)} – ${fmt$(r.wide_hi)}</strong>. Walk-forward, those bands covered 52.3% and 79.7% of
      held-out protocols against nominal 50% and 80% — they mean what they say, neither padded nor trimmed.</p>
    </div>
    <div class="card">
      <h3>The record</h3>
      <div class="facts">
        <div class="fact"><div class="k">TVL</div><div class="v">${fmt$(r.tvl_usd)}</div></div>
        <div class="fact"><div class="k">7-day change</div><div class="v">${fmtPct(r.change_7d)}</div></div>
        <div class="fact"><div class="k">Listed</div><div class="v">${r.listed_at ?? 'unrecorded'}</div></div>
        <div class="fact"><div class="k">Age</div><div class="v">${fmtAge(r.age_days)}</div></div>
        <div class="fact"><div class="k">DefiLlama</div><div class="v">defillama.com/protocol/${esc(r.slug)}</div></div>
      </div>
    </div>
    <div class="card">
      <h3>Farm plan</h3>
      <ol class="plan">${r.farm_steps.map((s) => `<li>${esc(s)}</li>`).join('')}</ol>
    </div>`;
}

// The ablation and held-out figures below are literals in this source on
// purpose: the generated data file is the one file the dossier truncates,
// so the evidence for the model has to live in the page itself.
function renderMethodology(app) {
  const ablation = [
    ['TVL x global median multiple', 'x5.168', 'baseline'],
    ['+ category multiples, shrunk toward the global median (k = 2)', 'x4.794', 'kept'],
    ['+ maturity factor (operating age)', 'x4.478', 'kept'],
    ['+ linear momentum on 7-day TVL change', 'x4.715', 'dropped — made held-out predictions worse'],
    ['+ banded momentum instead (only moves beyond +/-35%)', 'x4.449', 'kept — the final model'],
    ['+ concentration dampener (chains / audits / governance)', 'x4.574', 'dropped — made held-out predictions worse'],
  ].map((row) => `<tr><td>${row[0]}</td><td class="num">${row[1]}</td><td class="${row[2] === 'kept' ? 'kept' : row[2].startsWith('dropped') ? 'dropped' : ''}">${row[2]}</td></tr>`).join('');
  const ledgerRows = meta.ledger.map((g) =>
    `<tr><td>${esc(g.label)}</td><td class="num">${fmtInt(g.count)}</td><td>${esc(g.note)}</td></tr>`).join('');
  app.innerHTML = `
  <div class="method">
    <h2>Methodology</h2>
    <p>The board prices protocols that record no token. There is no market price for them yet, so the price has to be
    derived — and the only honest source is the snapshot itself. Every protocol in the snapshot that records a token and
    carries both a market cap and a TVL gives one observation: the multiple the market pays per dollar of TVL. A pre-token
    protocol is then priced at its own TVL times the multiple of its category, adjusted by two further terms that survived
    testing. Protocols that already trade are used only as comparables; they are never ranked, and the two populations are
    kept separate everywhere on this page.</p>
    <h3>The formula</h3>
    <p><strong>implied value = TVL x comparable multiple (category) x momentum factor x maturity factor</strong>, clamped to
    [$1,000,000, $100,000,000,000,000] and rounded to whole dollars. The category multiple is the median multiple of the
    category's tokened protocols, shrunk toward the global median multiple (${fmtMult(meta.global_median_multiple)}) with
    k = 2 pseudo-observations, so a category with one or two observations borrows strength from the whole snapshot instead
    of swinging on a single name; a category with no comparables uses the global median. Shrunk multiples are capped at
    the 95th percentile of all observed multiples (${fmtMult(meta.multiple_cap)}): on this snapshot exactly
    ${meta.capped_categories.length === 1 ? 'one category' : `${meta.capped_categories.length} categories`} —
    ${esc(meta.capped_categories.join(', ') || 'none')} — rested on a single comparable whose own multiple is about x400,
    and the cap is the only thing between that observation and a board price of 133x TVL. The cap was held to the same
    standard as every other term: held-out accuracy is identical with and without it (x4.449), because held-out tests
    never see the tail it binds. It is kept because the board, not the test set, is where that tail does its damage.</p>
    <p>The maturity factor is min(1.4, 1 + 0.35 x log10(1 + age in days / 365)); a protocol with no recorded listing date is
    priced at the median comparable age (${fmtInt(meta.median_age_days)} days) and its detail view says so. The momentum
    factor is 1.15 when 7-day TVL change is at least +35%, 0.88 when it is at most -35%, and 1.00 inside the band or when
    no change is recorded. Nothing else enters the price: no names are hardcoded, no outside data is fetched, and the
    model runs from the snapshot alone.</p>
    <h3>What was fitted, what was dropped, and why</h3>
    <p>Each candidate term was tested the same way: 10-fold cross-validation over the ${fmtInt(meta.comparables)} usable
    comparables (folds assigned by slug hash), category multiples computed from training folds only, and the typical miss
    measured as 10 to the power of the median absolute log10 error. A term stayed only if it lowered the held-out miss.</p>
    <table class="ablation"><thead><tr><th>Model</th><th class="num">Typical held-out miss</th><th>Decision</th></tr></thead>
    <tbody>${ablation}</tbody></table>
    <p>Held out, the final model prices a typical comparable within x4.45 of its actual market cap, lands within 2x for
    23% of comparables and within 5x for 53%. It also runs slightly hot: the median prediction is x1.36 times the actual.
    That bias is disclosed here rather than corrected away, because a correction fitted on the same 128 protocols would
    be one more untested term wearing a lab coat. Momentum's honest role is narrow: the banded form barely moves prices
    (x4.478 to x4.449) — its real work is in the verdicts, where a protocol shrinking by more than a third in a week is
    told to Skip rather than farmed into a decline.</p>
    <h3>The uncertainty interval on every row</h3>
    <p>Under each price on the board sits its P25–P75 interval, and each detail view adds the wider P10–P90 range. The
    multipliers come from this model's own leave-one-out residuals: every one of the ${fmtInt(meta.comparables)} comparables
    was repriced with multiples computed without it, and the distribution of actual over predicted gave P10 x0.043,
    P25 x0.155, P75 x4.119 and P90 x11.297. The bands were then checked the hard way — built from training folds only and
    tested on held-out protocols, the P25–P75 band covered 52.3% of actuals against a 50% nominal rate, and the P10–P90
    band covered 79.7% against 80% nominal. They are wide because launch pricing is wide; a narrower band would be a
    lie with better typography. Use the interval, not the point, when deciding how much of a farm a name deserves.</p>
    <h3>The completeness ledger</h3>
    <p>A radar that silently drops protocols is a radar that lies by omission. Every one of the snapshot's
    ${fmtInt(meta.snapshot_total)} protocols is in exactly one group below — priced as a comparable, ranked on the board,
    or set aside with the reason named. The groups are decided in the pipeline's own order: a token record first, then
    the ranking rule, then the first rule that sets a name aside. The counts are computed from the snapshot at build
    time, and they sum to the snapshot total.</p>
    <table class="ledger"><thead><tr><th>Group</th><th class="num">Protocols</th><th>What it means</th></tr></thead>
    <tbody>${ledgerRows}
    <tr><td><strong>Total</strong></td><td class="num"><strong>${fmtInt(meta.snapshot_total)}</strong></td><td>every protocol in the snapshot, counted once</td></tr></tbody></table>
    <h3>The ranking rule, and its limits</h3>
    <p>A protocol reaches the board when the snapshot records no token for it — no CoinGecko id and no symbol, with "-"
    read as no record — its category is not a bridge, liquid staking, restaking or exchange category, its name carries no
    version suffix and no wrapped or staked wording, it does not begin with an exchange brand, and its TVL is at least
    $5M. That leaves ${fmtInt(meta.board_rows)} ranked protocols: all ${meta.watchlist_covered} of the
    ${meta.watchlist_total} watchlist names, plus ${fmtInt(meta.early_candidates)} early candidates beyond it. Verdicts
    are rules, not vibes: Farm now needs watchlist membership, a year of history and $50M of TVL, or a billion-dollar
    implied value on $100M of TVL with two years of history; Skip is for sub-$10M TVL or a TVL collapse beyond the
    momentum band; everything else is Watch, with the missing ingredient named. Farm plans are generated per protocol
    from its chain (gas), its category (the work) and its TVL (the principal, 0.1% of TVL clamped to $250–$2,000), and
    each step carries its action, cost, time and risk. The board's limits are the snapshot's limits: one sealed moment,
    no live prices, and a model whose typical miss is printed above rather than hidden.</p>
  </div>`;
}

function route() {
  const app = document.getElementById('app');
  const hash = location.hash || '#/';
  document.getElementById('nav-board').classList.toggle('on', !hash.startsWith('#/methodology'));
  document.getElementById('nav-method').classList.toggle('on', hash.startsWith('#/methodology'));
  if (hash.startsWith('#/protocol/')) renderDetail(app, hash.slice('#/protocol/'.length));
  else if (hash.startsWith('#/methodology')) renderMethodology(app);
  else renderBoard(app);
}
window.addEventListener('hashchange', route);
route();
